def clean(df):
    df = df[(df['Quantity'].notna() & (df['Quantity'].astype(int) == df['Quantity']) & (df['Quantity'] > 0))
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    df = df[df['Category'].str.strip().isin(allowed)]
    return df

def answer(df):
    return df['Category'].value_counts().to_dict()
